/** Public three-column table, generated by scripts/build-emoji-catalog.js. */
import { EMOJI_IDENTITIES } from './identity-data'
import { EMOJI_LABELS } from './labels-data'

function composeEmojiData() {
  const data = {}
  for (const key of Object.keys(EMOJI_IDENTITIES)) {
    data[key] = EMOJI_IDENTITIES[key].map(([glyph, name], index) => [glyph, EMOJI_LABELS[key][index], name])
  }
  return data
}

const EMOJI_DATA = /*#__PURE__*/ composeEmojiData()
export { EMOJI_DATA }
